<script lang="ts">
  import {scrollRegion} from '#lib/client/scroll-region.ts';
  import {refreshAll} from '$app/navigation';import {command,display} from '#lib/client/api.ts';import {focusTrap} from '#lib/client/focus-trap.ts';import type {AppData,Row} from '#lib/client/types.ts';import Icon from './Icon.svelte';import Status from './Status.svelte';import TimeSnapshot from './TimeSnapshot.svelte';
  let {data}:{data:AppData}=$props();let current:Row|null=$state(null);let reason=$state('');let confirmed=$state(false);let busy=$state(false);let error=$state('');let notice=$state('');
  const submissions=$derived(data.related?.review_submissions||[]);const corrections=$derived(data.related?.review_corrections||[]);const own=$derived(data.related?.time_submissions||[]);let type=$state('submission');let decision=$state('approve');
  async function approve(event:SubmitEvent){event.preventDefault();if(!current||!confirmed)return;busy=true;error='';try{await command(type==='correction'?'workforce.time.correction.approve':decision==='return'?'workforce.time.return':'workforce.time.approve',current.id,{reason},current.version);current=null;confirmed=false;reason='';notice='Die geprüfte Zeitentscheidung wurde verbindlich gespeichert.';await refreshAll().catch(()=>{});}catch(e){error=e instanceof Error?e.message:'Die Zeitentscheidung konnte nicht gespeichert werden.';}finally{busy=false;}}
</script>
{#if own.length}<section class="panel"><header class="panel-header"><h2>Meine abgegebenen Tage</h2></header><div class="table-scroll" use:scrollRegion={'Meine abgegebenen Tage'}><table class="data-table"><thead><tr><th>Zeitraum</th><th>Stand</th><th>Prüfhinweise</th></tr></thead><tbody>{#each own as submission}<tr><td>{display(submission.starts_on,'date')}{submission.ends_on!==submission.starts_on?` – ${display(submission.ends_on,'date')}`:''}</td><td><Status value={submission.status}/></td><td>{submission.reason||submission.warnings?.join(' · ')||'Keine zusätzlichen Hinweise'}</td></tr>{/each}</tbody></table></div></section>{/if}
{#if data.context?.permissions.includes('time.approve')}<section class="panel"><header class="panel-header"><div><h2>Zeiten sachlich prüfen</h2><p>Die tatsächlichen Intervalle bleiben vollständig. Eigene Abgaben genehmigt eine andere Person.</p></div><span class="count">{submissions.length+corrections.length}</span></header><div class="panel-body">{#if notice}<div class="notice info" role="status">{notice}</div>{/if}{#each submissions as submission}<div class="integration-row"><div><h3>{submission.employee_name||display(submission.employee_id,'employee_id',data)}</h3><p>{display(submission.starts_on,'date')} · {submission.work_seconds!==undefined?`${(Number(submission.work_seconds)/3600).toLocaleString('de-DE',{maximumFractionDigits:2})} h tatsächlich`:''}</p><Status value={submission.status}/>{#if submission.warnings?.length}<p class="mt">{submission.warnings.join(' · ')}</p>{/if}</div><button class="btn small" disabled={submission.employee_id===data.context?.employeeId||submission.status!=='submitted'} onclick={()=>{current=submission;type='submission';decision='approve';confirmed=false;reason='';error='';}}>Abgabe prüfen</button></div>{/each}{#each corrections as correction}<div class="integration-row"><div><h3>Korrekturantrag · {correction.employee_name||display(correction.employee_id,'employee_id',data)}</h3><p>{correction.reason}</p><Status value={correction.status}/></div><button class="btn small" disabled={correction.employee_id===data.context?.employeeId||correction.status!=='requested'} onclick={()=>{current=correction;type='correction';confirmed=false;reason='';error='';}}>Korrektur prüfen</button></div>{/each}{#if !submissions.length&&!corrections.length}<div class="empty-state compact"><div class="empty-icon"><Icon name="check"/></div><h3>Keine fremden Abgaben zur Prüfung</h3><p>Eingereichte Zeiten und Korrekturanträge erscheinen hier im freigegebenen Zuständigkeitsbereich.</p></div>{/if}</div></section>{/if}
{#if current}<div class="modal-backdrop" role="presentation"><div class="modal wide" role="dialog" aria-modal="true" aria-labelledby="time-review-title" tabindex="-1" use:focusTrap onkeydown={(e)=>{if(e.key==='Escape'&&!busy)current=null;}}><header class="modal-header"><div><h2 id="time-review-title">{type==='correction'?'Korrektur nachvollziehbar freigeben':'Tatsächliche Zeiten prüfen'}</h2><p>{current.employee_name||display(current.employee_id,'employee_id',data)} · Version {current.version}</p></div><button class="icon-button" disabled={busy} aria-label="Schließen" onclick={()=>current=null}><Icon name="close"/></button></header><form onsubmit={approve} style="display:contents"><div class="modal-body">{#if error}<div class="notice error" role="alert">{error}</div>{/if}{#if current.warnings?.length}<div class="notice warning"><Icon name="alert"/><div>{current.warnings.join(' · ')}<p class="small mt">Die Bestätigung tatsächlicher Daten ist keine Feststellung, dass ein Regelverstoß zulässig war.</p></div></div>{/if}{#if type==='correction'}<div class="field-grid"><div><p class="section-label">Bisheriger Stand</p><TimeSnapshot snapshot={current.old_snapshot} {data}/></div><div><p class="section-label">Beantragter Stand</p><TimeSnapshot snapshot={current.new_snapshot} {data}/></div></div>{:else}<div class="action-preview"><p class="small">Zeitraum {display(current.starts_on,'date')} – {display(current.ends_on,'date')}</p><p class="small mt">Enthaltene Sitzungen: {current.session_ids?.length??'im Abgabestand gebunden'}</p>{#if current.revision_snapshot?.length}{#each current.revision_snapshot as snapshot}<div class="mt"><TimeSnapshot {snapshot} {data}/></div>{/each}{:else if current.segments?.length}<div class="mt"><TimeSnapshot snapshot={{segments:current.segments,allocations:current.allocations||[]}} {data}/></div>{:else}<p class="small mt">Der Antrag bindet die unveränderlich eingereichten Sitzungsrevisionen. Prüfen Sie die zugehörigen tatsächlichen Intervalle und Zuordnungen vor der Freigabe.</p>{/if}</div>{/if}{#if type==='submission'}<div class="field mt"><label for="time-review-decision">Entscheidung *</label><select id="time-review-decision" bind:value={decision}><option value="approve">Tatsächlichen Stand freigeben</option><option value="return">Mit Rückfrage zurückgeben</option></select><span class="field-help">Eine Rückfrage ändert keine aufgezeichneten Zeiten. Begründen Sie, was noch geklärt werden muss.</span></div>{/if}<div class="field mt"><label for="time-review-reason">Fachliche Begründung / betriebliche Maßnahme *</label><textarea id="time-review-reason" bind:value={reason} required minlength="5"></textarea></div><label class="check-field mt"><input type="checkbox" bind:checked={confirmed} required/><span>Ich habe die tatsächlichen Intervalle, Pausen, Zuordnungen und Prüfhinweise dieses Versionsstands geprüft.</span></label></div><footer class="modal-footer"><button type="button" class="btn" disabled={busy} onclick={()=>current=null}>Zurück</button><button class="btn primary" disabled={busy||!confirmed}>{busy?'Wird bestätigt …':type==='correction'?'Geprüfte Korrektur freigeben':decision==='return'?'Mit Rückfrage zurückgeben':'Tatsächlichen Stand freigeben'}</button></footer></form></div></div>{/if}
